// Granularidades del selector de tiempo.
window.AE_REAL_GRAN = [
  { id:'semana',    label:'Semanas',    n:12 },
  { id:'mes',       label:'Meses',      n:12 },
  { id:'trimestre', label:'Trimestres', n:8 },
];

const _mesesDe = (t) => { const y = +t.slice(0,4), q = +t.slice(6); return [1,2,3].map(i => y + '-' + String((q-1)*3+i).padStart(2,'0')); };
const _MES_L = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];

// Periodos disponibles de una granularidad, los más recientes al final.
window.aeRealPeriodos = function (gran, ows) {
  const store = gran === 'semana' ? window.AE_REAL_SEM : window.AE_REAL_MES;
  const keys = ows || Object.keys(store);
  const set = {};
  keys.forEach(ow => Object.keys(store[ow] || {}).forEach(k => { set[k] = true; }));
  let ids = Object.keys(set).sort();
  if (gran === 'trimestre') {
    const qs = {};
    ids.forEach(m => { qs[m.slice(0,4) + '-Q' + Math.ceil(+m.slice(5,7)/3)] = true; });
    ids = Object.keys(qs).sort();
  }
  const g = window.AE_REAL_GRAN.find(x => x.id === gran);
  if (g && ids.length > g.n) ids = ids.slice(ids.length - g.n);
  return ids.map(id => ({ id, label: window.aeRealLabel(gran, id) }));
};

window.aeRealLabel = function (gran, id) {
  if (!id) return '—';
  if (gran === 'trimestre') return id.replace('-', ' ');
  if (gran === 'semana') return 'sem ' + (+id.slice(6)) + ' · ' + id.slice(2,4);
  return _MES_L[+id.slice(5,7) - 1] + ' ' + id.slice(2,4);
};

// Bucket agregado de un AE en un periodo, opcionalmente de un solo canal. El
// trimestre suma sus tres meses; sin canal, suma los cuatro orígenes.
window.aeRealDe = function (ow, gran, id, canal) {
  if (!ow || !id) return null;
  const store = gran === 'semana' ? window.AE_REAL_SEM : window.AE_REAL_MES;
  const src = store[ow];
  if (!src) return null;
  const keys = gran === 'trimestre' ? _mesesDe(id) : [id];
  const o = { d:0, w:0, l:0, o:0, eurW:0, src:{}, alc:{disc:0,data:0,risk:0,nego:0,won:0}, alcEur:{disc:0,data:0,risk:0,nego:0,won:0} };
  let hay = false;
  keys.forEach(k => {
    const cs = src[k]; if (!cs) return;
    Object.keys(cs).forEach(can => {
      if (canal && canal !== 'todos' && can !== canal) return;
      const x = cs[can];
      hay = true;
      o.d += x.d; o.w += x.w; o.l += x.l; o.o += x.o; o.eurW += x.eurW;
      o.src[can] = (o.src[can] || 0) + x.d;
      Object.keys(x.alc).forEach(s => { o.alc[s] += x.alc[s]; o.alcEur[s] += x.alcEur[s]; });
    });
  });
  return hay ? o : null;
};

// Conversiones de etapa de una cohorte, con los nombres que usa dirección.
window.AE_REAL_CONV = [
  { id:'discRisk', label:'Discovery → Risk', de:'disc', a:'risk',
    desc:'De la reunión de descubrimiento al comité de riesgos: mide si el AE sabe sacar la documentación.' },
  { id:'riskNego', label:'Risk → Negociación', de:'risk', a:'nego',
    desc:'Tasa de aprobación: operaciones que pasan de riesgos a la mesa de negociación.' },
  { id:'negoWon',  label:'Negociación → Activación', de:'nego', a:'won',
    desc:'De la propuesta a la firma: mide si sabe cerrar el precio y el límite.' },
  { id:'actCli',   label:'Activación → Cliente', de:'won', a:null, estado:'pendiente',
    desc:'De la línea firmada a la línea dispuesta. HubSpot cierra el deal en WON y no distingue las dos cosas: hace falta separar activación de cliente con disposición para medirla.' },
];

